(()=>{const input=document.querySelector('#smart-search'),form=document.querySelector('#smart-search-form'),panel=document.querySelector('#smart-results'),list=document.querySelector('#smart-list'),status=document.querySelector('#smart-status');let businesses=[],ready=false;const norm=s=>s.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9 ]/g,' ').trim();const stops=new Set(['un','una','unos','unas','el','la','los','las','de','del','en','para','por','con','y','que','quiero','necesito','busco','buscar','me','mi','tengo','hay','al','a','se','su','como']);function distance(a,b){let row=Array.from({length:b.length+1},(_,i)=>i);for(let i=1;i<=a.length;i++){const next=[i];for(let j=1;j<=b.length;j++)next[j]=Math.min(next[j-1]+1,row[j]+1,row[j-1]+(a[i-1]!==b[j-1]));row=next}return row[b.length]}function matches(query){const words=norm(query).split(/\s+/).filter(w=>w&&!stops.has(w));if(!words.length)return [];return businesses.map(b=>{const names=norm(b.nombre).split(/\s+/),terms=norm(b.nombre+' '+b.detalle+' '+b.terminos).split(/\s+/);let score=0;for(const w of words){let best=0;for(const t of terms){if(t===w)best=Math.max(best,names.includes(t)?6:4);else if(w.length>=3&&t.startsWith(w))best=Math.max(best,2);else if(w.length>=5&&Math.abs(t.length-w.length)<=1&&distance(w,t)<=1)best=Math.max(best,1)}if(!best)return null;score+=best}return {b,score}}).filter(Boolean).sort((a,b)=>b.score-a.score).slice(0,9).map(x=>x.b)}function update(){const query=input.value.trim();if(!query){panel.hidden=true;input.setAttribute('aria-expanded','false');return}panel.hidden=false;input.setAttribute('aria-expanded','true');list.replaceChildren();if(!ready){status.textContent='Cargando negocios…';return}const results=matches(query);status.textContent=results.length?results.length+' '+(results.length===1?'opción encontrada':'opciones encontradas'):'No encontramos una coincidencia. Probá con el servicio o el nombre del negocio.';for(const b of results){const a=document.createElement('a');a.className='finder-result';a.href=b.url;const img=document.createElement('img');img.src=b.imagen;img.alt='';const copy=document.createElement('div');const title=document.createElement('strong');title.textContent=b.nombre;const detail=document.createElement('span');detail.textContent=b.detalle;copy.append(title,detail);const action=document.createElement('em');action.textContent='VER FICHA';a.append(img,copy,action);list.append(a)}}input.addEventListener('input',update);input.addEventListener('focus',()=>{if(input.value.trim())update()});input.addEventListener('keydown',e=>{if(e.key==='Escape'){panel.hidden=true;input.setAttribute('aria-expanded','false')}if(e.key==='ArrowDown'){const first=list.querySelector('a');if(first){e.preventDefault();first.focus()}}});form.addEventListener('submit',e=>{e.preventDefault();update()});document.addEventListener('click',e=>{if(!e.target.closest('.header-finder')){panel.hidden=true;input.setAttribute('aria-expanded','false')}});fetch('datos/buscador-negocios.json').then(r=>{if(!r.ok)throw Error();return r.json()}).then(data=>{businesses=data;ready=true;if(input.value.trim())update()}).catch(()=>{ready=true;status.textContent='No pudimos cargar el buscador. Intentá recargar la página.'});})();
